@push('scripts')<script>document.addEventListener('hris:ready',()=>{const requirements=document.querySelector('#requirements-table'),plans=document.querySelector('#plans-table'),form=document.querySelector('#requirement-form');let currentPlan=null;HRIS.bindForm(form,{success:()=>requirements.table.load()});HRIS.bindForm(document.querySelector('#plan-form'),{success:()=>plans.table.load()});requirements.addEventListener('table:action',async({detail:{action,row}})=>{if(action==='edit'){HRIS.fillForm(form,row);form.dataset.endpoint=`/learning-development/requirements/${row.id}`;form.dataset.method='PUT';HRIS.openModal('requirement-modal')}else if(await HRIS.confirm('Archive this requirement? Historical links will remain.')){try{HRIS.feedback((await HRIS.request(`/learning-development/requirements/${row.id}/archive`,{method:'PATCH'})).message);requirements.table.load()}catch(e){HRIS.feedback(e.message,true)}}});plans.addEventListener('table:action',async({detail:{row}})=>{currentPlan=row;try{const items=await HRIS.request(`/learning-development/plans/${row.id}/eligible-items`),existing=new Map((row.lines||[]).map(line=>[String(line.idp_item_id),line])),list=document.querySelector('#plan-lines-list');list.replaceChildren();items.forEach(item=>{const saved=existing.get(String(item.id)),wrap=document.createElement('label');wrap.className='border rounded p-3 d-grid gap-2';wrap.innerHTML='<span class="fw-semibold"></span><span class="small text-body-secondary"></span><span class="d-flex gap-3 align-items-center"><input type="checkbox" data-include> Include <input class="form-control" type="number" min="0" step="0.01" data-budget aria-label="Budget"><span><input type="checkbox" data-free> Free</span></span>';wrap.dataset.itemId=item.id;wrap.querySelector('.fw-semibold').textContent=item.title;wrap.querySelector('.text-body-secondary').textContent=`${item.plan.employee.name} - ${item.proposal}`;wrap.querySelector('[data-include]').checked=Boolean(saved);wrap.querySelector('[data-budget]').value=saved?.budget??0;wrap.querySelector('[data-free]').checked=Boolean(saved?.is_free);list.append(wrap)});document.querySelector('#print-plan').href=`/learning-development/plans/${row.id}/print`;HRIS.openModal('plan-lines-modal')}catch(e){HRIS.feedback(e.message,true)}});document.querySelector('#save-plan-lines').onclick=async()=>{const lines=[...document.querySelectorAll('#plan-lines-list [data-item-id]')].filter(row=>row.querySelector('[data-include]').checked).map(row=>({idp_item_id:Number(row.dataset.itemId),budget:Number(row.querySelector('[data-budget]').value||0),is_free:row.querySelector('[data-free]').checked}));try{HRIS.feedback((await HRIS.request(`/learning-development/plans/${currentPlan.id}/lines`,{method:'PUT',body:{lines}})).message);plans.table.load()}catch(e){HRIS.feedback(e.message,true)}}});</script>@endpush
